            //
            aOrbiterD = (aOrbiterD + aOrbiterA) + 0x265954B4F3F65C1DULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterD) ^ 0xE65225E7D24C2CC2ULL) ^ aOUSaltD[((aIndex + 145U)) & S_SALT1];
