            aCross ^= (RotL64(pCrossLaneA[((S_BLOCK1 - aIndex + 16151U)) & S_BLOCK1], 27U) ^ RotL64(aFireLaneB[((S_BLOCK1 - aIndex + 16172U)) & S_BLOCK1], 53U));
            aCross = TwistMix64::DiffuseC((aCross ^ aTwistDomainWordCross));
            //
            aScatter = (RotL64(aIngress, 29U) ^ RotL64(aCross, 5U)) + (RotL64(aCarry, 57U) ^ RotL64(aPrevious, 42U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterD = ((aWandererE + RotL64(aPrevious, 11U)) + 0xEEBC80B62B4D9B52ULL) + aOASaltE[((aIndex + 45U)) & S_SALT1];
