            aWandererF = aWandererF ^ ((RotL64(aScatter, 52U) + RotL64(aOrbiterA, 21U)) + aOrbiterG);
            aWandererG = aWandererG + (((RotL64(aIngress, 39U) + aOrbiterD) + RotL64(aOrbiterF, 51U)) + RotL64(aCarry, 23U));
            aWandererD = aWandererD ^ ((RotL64(aScatter, 43U) + aOrbiterJ) + RotL64(aOrbiterD, 36U));
